const sortArticlesByDate = (items: ArticleData[]): ArticleData[] =>
  [...items].sort(
    (a, b) => new Date(b.datePublished).getTime() - new Date(a.datePublished).getTime(),
  );

export { sortArticlesByDate };

export const fallbackArticleData = sortArticlesByDate(articleDataUnsorted);

export type ArticleItem = ArticleData;

export const slugFromLink = (link: string) => {
  const segments = link.split('/').filter(Boolean);
  return segments[segments.length - 1] ?? '';
};

export const getFallbackArticleBySlug = (slug: string): ArticleData | undefined =>
  fallbackArticleData.find(
    (item) => slugFromLink(item.link) === slug || item.link.includes(slug),
  );

export const getArticleSlugs = (articles: ArticleData[] = fallbackArticleData): string[] =>
  articles.map((item) => slugFromLink(item.link)).filter(Boolean);

export const getArticleBySlug = (
  slug: string,
  articles: ArticleData[] = fallbackArticleData,
): ArticleData | undefined =>
  articles.find((item) => slugFromLink(item.link) === slug || item.link.includes(slug));

export const getLatestArticles = (
  articles: ArticleData[],
  limit = LATEST_ARTICLES_COUNT,
) => sortArticlesByDate(articles).slice(0, limit);

export const getRecentArticles = (
  articles: ArticleData[],
  excludeLink: string,
  limit = RECENT_ARTICLES_DETAIL_COUNT,
) =>
  sortArticlesByDate(articles)
    .filter((article) => article.link !== excludeLink)
    .slice(0, limit);

export type ArticleCategorySection = {
  id: string;
  label: string;
  articles: ArticleData[];
};

export const articleMatchesSearchQuery = (
  article: ArticleData,
  query: string,
  categories: ArticleCategory[] = FALLBACK_ARTICLE_CATEGORIES,
): boolean => {
  const normalizedQuery = query.trim().toLowerCase();
  if (!normalizedQuery) return true;

  const categoryLabel = (
    article.categoryLabel ?? getArticleCategoryLabel(article.category, categories)
  ).toLowerCase();
  const haystack = [
    article.title,
    article.seoTitle,
    article.seoDescription,
    categoryLabel,
  ]
    .join(' ')
    .toLowerCase();

  return haystack.includes(normalizedQuery);
};

export const searchArticles = (
  articles: ArticleData[],
  query: string,
  categories: ArticleCategory[] = FALLBACK_ARTICLE_CATEGORIES,
): ArticleData[] => {
  const normalizedQuery = query.trim();
  if (!normalizedQuery) return [];

  return sortArticlesByDate(articles).filter((article) =>
    articleMatchesSearchQuery(article, normalizedQuery, categories),
  );
};

export const getArticlesByCategory = (
  articles: ArticleData[],
  categoryId: ArticleCategoryId,
  excludeLinks: ReadonlySet<string> = new Set(),
): ArticleData[] => {
  const normalized = normalizeArticleCategoryId(categoryId);
  return sortArticlesByDate(articles).filter(
    (article) =>
      normalizeArticleCategoryId(article.category) === normalized &&
      !excludeLinks.has(article.link),
  );
};

export type PaginatedResult<T> = {
  items: T[];
  page: number;
  pageSize: number;
  totalItems: number;
  totalPages: number;
};

export const paginateItems = <T>(
  items: T[],
  page: number,
  pageSize: number,
): PaginatedResult<T> => {
  const totalItems = items.length;
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const safePage = Math.min(Math.max(1, page), totalPages);

  return {
    items: items.slice((safePage - 1) * pageSize, safePage * pageSize),
    page: safePage,
    pageSize,
    totalItems,
    totalPages,
  };
};

export const getArticleCategorySections = (
  articles: ArticleData[],
  excludeLinks: ReadonlySet<string> = new Set(),
  categories: ArticleCategory[] = FALLBACK_ARTICLE_CATEGORIES,
): ArticleCategorySection[] => {
  const byCategory = new Map<string, ArticleData[]>();
  const knownIds = new Set(categories.map((category) => category.id));

  for (const article of sortArticlesByDate(articles)) {
    const categoryId = normalizeArticleCategoryId(article.category);
    if (!categoryId || !knownIds.has(categoryId)) continue;
    if (excludeLinks.has(article.link)) continue;

    const existing = byCategory.get(categoryId) ?? [];
    existing.push(article);
    byCategory.set(categoryId, existing);
  }

  return categories
    .slice()
    .sort((a, b) => a.sortOrder - b.sortOrder || a.label.localeCompare(b.label))
    .filter((category) => byCategory.has(category.id))
    .map((category) => ({
      id: category.id,
      label: category.label,
      articles: byCategory.get(category.id)!,
    }));
};
